import{_ as a,a as t,c as o,ac as r}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第四册：流利英语 · Lesson 48 Planning a share portfolio","description":"学习 决策段落中的 however、therefore 与条件，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 48 Planning a share portfolio","description":"学习 决策段落中的 however、therefore 与条件，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 决策段落中的 however、therefore 与条件，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 47 The great escape","link":"/life/english/new-concept/book-4/unit-06/lesson-047"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 47 The great escape","link":"/life/english/new-concept/book-4/unit-06/lesson-047"},"next":false},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-048.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-048.md"}'),n={name:"life/english/new-concept/book-4/unit-06/lesson-048.md"};function i(l,e,s,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="第四册-流利英语-·-lesson-48-planning-a-share-portfolio" tabindex="-1">第四册：流利英语 · Lesson 48 Planning a share portfolio <a class="header-anchor" href="#第四册-流利英语-·-lesson-48-planning-a-share-portfolio" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 48 Planning a share portfolio&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以股票组合规划这一议论题材练习阅读决策文本，区分目标、约束、假设与不确定结果。只使用虚构情境说明语言，不推荐证券或给出个人配置比例。重点将理由、让步和结论组织成连贯段落，理解分散选择可以改变风险暴露，但不等于保证收益或排除损失。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>portfolio</td><td>/pɔːtˈfəʊliəʊ/</td><td>n.</td><td>投资组合</td><td>a hypothetical portfolio</td></tr><tr><td>diversification</td><td>/daɪˌvɜːsɪfɪˈkeɪʃən/</td><td>n.</td><td>分散配置</td><td>portfolio diversification</td></tr><tr><td>uncertainty</td><td>/ʌnˈsɜːtnti/</td><td>n.</td><td>不确定性</td><td>acknowledge uncertainty</td></tr><tr><td>objective</td><td>/əbˈdʒektɪv/</td><td>n.</td><td>目标</td><td>define an objective</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>depend on — 取决于具体条件</li><li>take into account — 将某因素纳入考虑</li></ul><h2 id="语法讲解-决策段落中的-however、therefore-与条件" tabindex="-1">语法讲解：决策段落中的 however、therefore 与条件 <a class="header-anchor" href="#语法讲解-决策段落中的-however、therefore-与条件" aria-label="Permalink to &quot;语法讲解：决策段落中的 however、therefore 与条件&quot;">​</a></h2><p>however 引入转折，therefore 引出推论，for example 提供实例；它们通常是连接副词，不能只用一个逗号拼接两个独立句。可写 The options differ; therefore, we need a clear criterion，或分成两句。if 从句为结论设条件，provided that 表在某前提成立时。连接词应反映真实逻辑关系；没有支持理由时加 therefore 不会让结论自动有效。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The two plans serve different objectives; therefore, comparing returns alone would be misleading.</p></blockquote><p>这两种方案服务于不同目标；因此，只比较回报会产生误导。</p><p>分号连接独立分句；therefore 表由目标不同推导出的比较限制；comparing… 为动名词主语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The plans differ, however they… 是逗号拼接；应在 however 前用句号或分号，并根据结构加逗号。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 therefore 前做逻辑停顿；重读 objectives 与 alone，最后用 however 换写另一句，比较转折和推论的语气。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The first step is to define the purpose of the hypothetical portfolio. Future outcomes remain uncertain, even when the choices are spread across several categories. Therefore, any comparison should consider assumptions and constraints as well as possible returns.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构方案评估，不给投资建议：明确目标、指出一种不确定性、说明比较原则。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>按目标、不确定性、评价原则展开；未承诺分散一定获利，也未给出个人买卖建议。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改标点：The assumptions differ, therefore the results are not directly comparable.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The assumptions differ; therefore, the results are not directly comparable.</p><p><strong>解析：</strong> therefore 不是并列连词，不能仅用逗号连接独立句。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例认为只比较什么会误导？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 回报。</p><p><strong>解析：</strong> comparing returns alone 明确指出过度简化的指标。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>表示转折应选 however 还是 therefore？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> however</p><p><strong>解析：</strong> therefore 表推论，however 表转折。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：决策段落中的 however、therefore 与条件。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-047">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/review">全册自测</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(n,[["render",i]]);export{f as __pageData,u as default};
